	error_reporting(0);

	$strFileName				= "RssFeed.xml";
	$strDomain					= "http://".$_SERVER["HTTP_HOST"];
            
	$strRSSHeader				= "<?xml version=\"1.0\" ?>\n<rss version=\"2.0\">\n  <channel>\n";
	$strRSSChannel				= "    <title>".$SiteName."</title>\n    <link>".$strDomain."</link>\n    <description>Recent ".$SiteName." Articles</description>\n    <language>en-us</language>\n";
	$strRSSFooter				= "  </channel>\n</rss>";
	
	$dirList					= opendir("../Articles");            
		
	while (($dirPart = @readdir($dirList)) == true) 
		{  											
			if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
				{								
					$url		= $strDomain.rtrim(str_replace($DOCUMENT_ROOT, "",dirname(dirname($PHP_SELF))), "/")."/Articles/".$dirPart;
					$tags		= get_meta_tags("../Articles/".$dirPart);					
					$Title		= str_replace(".php", "", str_replace("_", " ", $dirPart));								
					
					if(!stristr($tags['description'], "Index of All Articles in the"))
						{
							$strNode   .=  "    <item>\n      <title>".$Title."</title>\n      <description>".$tags['description']."</description>\n      <link>".$url."</link>\n      <guid>".$url."</guid>    </item>\n";
						}	
				}
		}
            
	closedir($dirList);

	$strRSSFeed					= $strRSSHeader.$strRSSChannel.$strNode.$strRSSFooter;
		          
	$fp							= fopen("../".$strFileName, "w" );
	fwrite($fp, $strRSSFeed);
	fclose( $fp );
        
?>